from pathlib import Path
exec(Path('tools/test-map-browser.py').read_text(encoding='utf8').split("cmd('Emulation.setDeviceMetricsOverride'")[0])
cmd('Page.enable');cmd('Network.enable');cmd('Network.setCacheDisabled',{'cacheDisabled':True})
cmd('Page.addScriptToEvaluateOnNewDocument',{'source':'window.errors=[];window.addEventListener("error",e=>errors.push(e.message));'})
cmd('Emulation.setDeviceMetricsOverride',{'width':1280,'height':900,'deviceScaleFactor':1,'mobile':False})
cmd('Page.navigate',{'url':base+'compare.html'})
wait("document.getElementById('compare-photo').onchange")
ev("localStorage.removeItem('kdrama-compare-simple-v1')")
cmd('Page.reload');wait("document.getElementById('compare-photo').onchange")
ev("window.byId=id=>document.getElementById(id);window.makeFile=async(w,h,color)=>{const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle=color;x.fillRect(0,0,w,h);return new File([await new Promise(r=>c.toBlob(r))],'test.png',{type:'image/png'})};void 0")
assert ev("byId('compare-download').disabled && document.querySelector('[data-mode=vertical]').getAttribute('aria-pressed')==='true'")
ev("(async()=>{for(const [kind,w,h,color] of [['scene',200,100,'red'],['photo',100,100,'blue']]){const d=new DataTransfer();d.items.add(await makeFile(w,h,color));byId(kind+'-zone').dispatchEvent(new DragEvent('drop',{dataTransfer:d,bubbles:true,cancelable:true}));}})()")
wait("!document.getElementById('compare-download').disabled")
assert ev("byId('compare-preview').height===2400")
assert ev("(()=>{const c=byId('compare-preview').getContext('2d');return c.getImageData(10,10,1,1).data[0]===255&&c.getImageData(10,2000,1,1).data[2]===255})()")
ev("document.querySelector('[data-mode=side]').click()")
assert ev("byId('compare-preview').height===533")
ev("byId('compare-gap').value='30';byId('compare-gap').dispatchEvent(new Event('input'));byId('compare-download').click()")
wait("document.getElementById('compare-save-dialog').open && document.getElementById('compare-result').naturalWidth>0")
assert ev("byId('save-file').download.endsWith('.png') && byId('save-file').href.startsWith('blob:')")
ev("byId('close-save').click();byId('scene-zone').dispatchEvent(new Event('focusin'));void 0")
ev("(async()=>{const d=new DataTransfer();d.items.add(await makeFile(150,150,'green'));document.dispatchEvent(new ClipboardEvent('paste',{clipboardData:d,bubbles:true,cancelable:true}));})()")
wait("document.getElementById('scene-image').naturalWidth===150")
assert ev("byId('photo-image').naturalWidth===100")
cmd('Emulation.setDeviceMetricsOverride',{'width':390,'height':844,'deviceScaleFactor':1,'mobile':True})
assert ev('document.documentElement.scrollWidth<=innerWidth+1')
